'ob.new_from_ticket' => 'Оферта',
'ob.no_offers_vessel' => 'Още няма оферта за този кораб.',
'ob.texts_title' => 'Текстове на оферти',
'ob.texts_lede' => 'Текстовите блокове на документа на офертата — въведение, обхват, изключения, валидност, цени и плащане, условия, заключение — по оформление, език, клон и клиент. Копират се във всяка нова оферта, където могат да се редактират.',
'ob.texts_none' => 'Още няма шаблон — важат вградените текстове. Добавете с бутоните вдясно.',
'ob.block' => 'Блок',
'ob.texts_resolve' => 'Кой шаблон важи: най-специфичният активен — клиент, после клон, после език, после оформление; шаблон, обвързан с друг клиент, клон, език или оформление, никога не се ползва. Езикът е този на порталните акаунти на клиента.',
'ob.text_name_ph' => 'напр. Условия — италиански клон',
'ob.any_layout' => '— всяко оформление —',
'ob.builtin_of' => 'Вграден текст',
'ob.texts_order' => 'Ред в документа: Въведение · Обхват · Цени (таблица) · Изключения · Валидност · Цени и плащане · Общи условия · Заключение. Празен блок не се печата.',
'ob.d_intro' => "Уважаеми господа,\n\nБлагодарим за запитването. В продължение на разговора ни имаме удоволствието да ви представим нашата оферта {no} за {vessel}, подробно описана по-долу.",
'ob.d_scope' => 'Офертата обхваща услугите и доставките от ценовата таблица. Работата се извършва от квалифицирани инженери на Golden A/S съгласно инструкциите на производителите, приложимите изисквания на класа и флага и Общите условия за услуги на Golden A/S.',
'ob.d_scope_system' => 'Офертата обхваща проектирането, доставката, надзора на монтажа, пускането в експлоатация и документацията на системата от ценовата таблица, съгласно инструкциите на производителите, приложимите изисквания на класа и флага и Общите условия за услуги на Golden A/S.',
'ob.d_scope_remote' => 'Офертата обхваща услугите, оборудването и плановете за дистанционна поддръжка от ценовата таблица по програмата Remote Support & AR — OceanOpulence™, съгласно Общите условия за услуги на Golden A/S.',
'ob.d_exclusions' => 'Освен ако е посочено в ценовата таблица, не са включени: резервни части и материали; пътуване, настаняване и дневни (по ценоразписа на Golden A/S); такси за клас, флаг и пристанище; работа извън нормалното работно време; закъснения извън контрола на Golden A/S.',
'ob.d_validity' => 'Офертата е валидна {validity_days} дни, до {valid_until}.',
'ob.d_payment' => 'Цените са в {currency}, без ДДС, където е приложимо. Часовите услуги се фактурират по действително отработените часове съгласно приложените тарифи, с минималните такси на тарифната карта; фиксираните цени — както е посочено. Плащане с банков превод или кредитна карта съгласно нашите Общи условия за услуги.',
'ob.d_terms' => 'Извънредни дневни и часови тарифи се прилагат в събота, неделя, празници и над осем (8) часа от понеделник до петък в Гърция или десет (10) часа в чужбина и на гръцките острови. Време за пътуване, фиксирани дневни, километри и пътни разходи — по ценоразписа на Golden A/S {rate_list}. В определените ремонтни зони в Гърция се дължи публична такса 180,00 € за разрешително за работа.',
'ob.d_closing' => "Надяваме се горното да отговаря на изискванията ви и оставаме на разположение за всякакви уточнения.\n\nС уважение,\n{user}\n{branch}",
