'eng.no_alerts' => 'Всички инженерни секции са в рамките на бюджета.',
'eng.blocked' => '{s}: {a} h отчетени срещу {b} h разрешени — още {n} h не могат да се отчетат. Първо заявете допълнителни часове от ръководството (или обявете секцията за завършена).',
'eng.activity_hint' => 'Етапът, на който е отработен този ред — той определя срещу бюджета на коя секция се броят часовете. Друг обект / сервиз не се брои срещу никоя секция.',
